            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;

        (uint256 afterUnlockTime, uint256 afterHolderBalance) = c.Acc(address(this));

        if (!reverted && collectAmount > 0) {
            assert(cBalanceAfter == cBalanceBefore + putAmount - collectAmount);
        } else {
            assert(cBalanceAfter == cBalanceBefore + putAmount);
        }

        assert(beforeUnlockTime == afterUnlockTime);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 putAmount, uint256 unlockTime, uint256 collectAmount) public payable {
        require(address(this).balance >= putAmount, "not enough balance");

        uint256 cBalanceBefore = address(c).balance;
        uint256 minSum = c.MinSum();

        c.Put{value: putAmount}(unlockTime);

        (uint256 beforeUnlockTime, uint256 beforeHolderBalance) = c.Acc(address(this));

        bool shouldSucceed = beforeHolderBalance >= minSum && beforeHolderBalance >= collectAmount && block.timestamp > beforeUnlockTime;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;
        (uint256 afterUnlockTime, uint256 afterHolderBalance) = c.Acc(address(this));

        if (!reverted) {
            assert(shouldSucceed);
            assert(cBalanceAfter == cBalanceBefore + putAmount - collectAmount);
            assert(afterHolderBalance == beforeHolderBalance - collectAmount);
        } else {
            assert(!shouldSucceed || collectAmount > beforeHolderBalance);
            assert(cBalanceAfter == cBalanceBefore + putAmount);
            assert(afterHolderBalance == beforeHolderBalance);
        }

        assert(afterUnlockTime == beforeUnlockTime);
    }

    receive() external payable {}
}
